// spec: .qa/e2e/specs/zmanim.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const clean = (s: string | null) => (s ?? '').replace(/[ ‎‏]/g, ' ').replace(/\s+/g, ' ').trim();

async function checkRow(page: Page, id: string, name: string) {
  const nameEl = page.locator(`#${id}-name`);
  const timeEl = page.locator(`#${id}-time`);
  await expect(nameEl).toHaveText(name);
  await expect(timeEl).toHaveText(/^\d{1,2}:\d{2}$/);
  const n = (await nameEl.boundingBox())!;
  const t = (await timeEl.boundingBox())!;
  // имя и час рядом: на одной строке
  expect(Math.abs(n.y - t.y)).toBeLessThan(2);
  return { n, t };
}

test.describe('זמני היום', () => {
  test('ZM-01 Строки זמנים: имя + час рядом, полное название метода, без переносов — мобильные ширины #6a86f7df @prod-safe @mobile', async ({ page }) => {
    // 1. Для каждой ширины 320, 360, 390: установить ширину и открыть `/zmanim`.
    for (const width of [320, 360, 390]) {
      await page.setViewportSize({ width, height: 844 });
      await page.goto('/zmanim');
      await expect(page.locator('#zmanim-times')).toBeVisible();

      // 2. Найти строки «בין השמשות», «צאת הכוכבים (רבנו תם…)», «סוף זמן קריאת שמע (מג״א, 72 דקות)».
      // «בין השמשות» + полное название метода на второй строке тем же шрифтом
      const bein = await checkRow(page, 'zman-beinHaShmashos', 'בין השמשות');
      const beinMethod = page.locator('#zman-beinHaShmashos-method');
      const beinMethodText = clean(await beinMethod.textContent());
      expect(beinMethodText).toContain('רבנו תם');
      expect(beinMethodText).toContain('13.5 דקות לפני');
      expect(beinMethodText).not.toContain('ר״ת');
      // «°» стоит после числа
      expect(clean(await beinMethod.textContent())).toMatch(/7\.083°/);
      const m = (await beinMethod.boundingBox())!;
      expect(m.y).toBeGreaterThan(bein.n.y + 10);
      const nameEl = page.locator('#zman-beinHaShmashos-name');
      for (const css of ['font-size', 'font-family', 'font-weight']) {
        const expected = await nameEl.evaluate((el, p) => getComputedStyle(el).getPropertyValue(p), css);
        await expect(beinMethod).toHaveCSS(css, expected);
      }

      // «צאת הכוכבים (רבנו תם, 72 דקות)» — имя + час + своё название метода
      await checkRow(page, 'zman-tzeit72min', 'צאת הכוכבים');
      const tzeitMethod = clean(await page.locator('#zman-tzeit72min-method').textContent());
      expect(tzeitMethod).toContain('רבנו תם');
      expect(tzeitMethod).toContain('72 דקות');

      // «סוף זמן קריאת שמע (מג״א, 72 דקות)» — название в одну строку
      const sof = await checkRow(page, 'zman-sofZmanShmaMGA', 'סוף זמן קריאת שמע');
      expect(clean(await page.locator('#zman-sofZmanShmaMGA-method').textContent())).toBe('(מג״א, 72 דקות)');
      expect(sof.n.height).toBeLessThanOrEqual(26);
      const sofMethod = (await page.locator('#zman-sofZmanShmaMGA-method').boundingBox())!;
      expect(sofMethod.height).toBeLessThanOrEqual(26);

      // Нет горизонтальной прокрутки
      const noHScroll = await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth);
      expect(noHScroll).toBe(true);
    }
  });
});
